  FT["PH-H2536"] = {"id":"PH-H2536","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2809_1960.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Catarman市","en":"An Act Establishing a School of Nursing and Midwifery in the Municipality of Catarman, Province of Samar, to be Attached to the Northern Samar, General Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a School of Nursing and Midwifery in the Municipality of Catarman, Province of Samar, to be Attached to the Northern Samar, General Hospital, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","health"],"docNumber":"Republic Act No. 2809","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2809_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2536-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Medical Services, a school of nursing and midwifery in the Municipality of Catarman, Province of Samar, to be attached to the Northern Samar General Hospital."}},{"id":"PH-H2536-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Medical Services shall, with the approval of the Secretary of Health, issue such rules and regulations as may be necessary to carry into effect the purpose of this Act."}},{"id":"PH-H2536-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, for the establishment, operation and maintenance of said school."}},{"id":"PH-H2536-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2537"] = {"id":"PH-H2537","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2810_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Sogod市","en":"An Act Creating Certain Barrios in the Municipality of Sogod, Province of Leyte","orig":"An Act Creating Certain Barrios in the Municipality of Sogod, Province of Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2810","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2810_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2537-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Sogod, Province of Leyte, are hereby converted or constituted into barrios:\na. Sitios Kantabuan, Baycasili, Mamingaw, Tagabaca and Kampuwa, into a barrio to be named Barrio Kauswagan;\nb. Sitio Ilo, into a barrio to be named Barrio Malinaw; and\nc. Sitios Hubasan, Agta, Manduduknay, Kabas-an and Cabadbaran, into a barrio to be named Barrio San Juan."}},{"id":"PH-H2537-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2538"] = {"id":"PH-H2538","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2811_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Minalin市","en":"An Act Creating Certain Barrios in the Municipality of Minalin, Province of Pampanga","orig":"An Act Creating Certain Barrios in the Municipality of Minalin, Province of Pampanga"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2811","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2811_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2538-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Dawe and Maniañgo in the Municipality of Minalin, Province of Pampanga, are converted into barrios of said municipality to be known as the barrios of Dawe and Maniañgo, respectively."}},{"id":"PH-H2538-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2539"] = {"id":"PH-H2539","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2812_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Sindangan市","en":"An Act Creating the Barrio of Talinga in the Municipality of Sindangan, Province of Zamboanga del Norte","orig":"An Act Creating the Barrio of Talinga in the Municipality of Sindangan, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2812","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2812_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2539-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Talinga in the Municipality of Sindangan, Province of Zamboanga del Norte, is converted into a barrio of said municipality to be known as the barrio of Talinga."}},{"id":"PH-H2539-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2540"] = {"id":"PH-H2540","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2813_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Maribojoc市","en":"An Act Creating the Barrio of Toril in the Municipality of Maribojoc, Province of Bohol","orig":"An Act Creating the Barrio of Toril in the Municipality of Maribojoc, Province of Bohol"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2813","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2813_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2540-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Toril in the Municipality of Maribojoc, Province of Bohol, is converted into a barrio of said municipality to be known as the barrio of Toril."}},{"id":"PH-H2540-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2541"] = {"id":"PH-H2541","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2814_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Casiguran市","en":"An Act Creating Certain Barrios in the Municipality of Casiguran, Province of Sorsogon","orig":"An Act Creating Certain Barrios in the Municipality of Casiguran, Province of Sorsogon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2814","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2814_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2541-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following places and sitios in the Municipality of Camarines, Province of Sorsogon, are declared as barrios thereof, to wit:\n1. The sitios of Cabogñahan, Cagdagat, Fabrica, Lubas and Marines, as a distinct and independent barrio to be known as the barrio of Boton;\n2. The sitio of Mambot and Namuut, as a distinct and independent barrio to be known as the barrio of Burgos;\n3. The barrio of Casay as barrio Casay;\n4. The barrio of Cogon as barrio Cogon;\n5. The barrio of Inlagadean as barrio Inlagadean;\n6. The barrio of Lugñid as barrio Lugñid;\n7. The barrio of Mabini as barrio Mabini;\n8. The sitio of Pamakiran as a barrio to be known as the barrio of Ponong;\n9. The sitios of Colambis, Lugi, Malagomgom, Rawag and Tiris, as a distinct and independent barrio to be known as the barrio of Rizal;\n10. The barrio of San Antonio as barrio San Antonio;\n11. The sitios of Tigbao and Nabugñaren, as a distinct and independent barrio to be known as the barrio of San Isidro;\n12. The sitio of Escuela, as a barrio to be known as the barrio of San Juan;\n13. The sitios of Cadiang and Purog, as a distinct and independent barrio to be known as the barrio of San Pascual;\n14. The sitios of Buraburan, Calayogan, Sog-ong and Talahib, as a distinct and independent barrio to be known as the barrio of Santa Cruz;\n15. The sitios of Mauhang and Storeroom, as a distinct and independent barrio to be known as the barrio of Trece Martires; and\n16. The sitios of Adovis, Busing, Cawit, Central, Somalot, Timbayog, Tinampo and Tulay, as a distinct and independent barrio to be known as the barrio of Poblacion."}},{"id":"PH-H2541-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
