  FT["PH-H2543"] = {"id":"PH-H2543","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2816_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立San Narciso市","en":"An Act Creating the Barrio of Villa Reyes in the Municipality of San Narciso, Province of Quezon","orig":"An Act Creating the Barrio of Villa Reyes in the Municipality of San Narciso, Province of Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2816","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2816_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2543-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Komaya, Rekudo and Iba are separated from the barrio of Vigo Cantidang in the Municipality of San Narciso, Province of Quezon, and constituted into a new barrio to be known as Barrio Villa Reyes of the same municipality, which shall be bounded on the North by Cantidang Creek, on the East by Ragay Gulf, on the West by Pugahanin and Mayho Ranges, and on the South by Bahay River."}},{"id":"PH-H2543-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
