  FT["PH-H2546"] = {"id":"PH-H2546","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2819_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Reappropriating Certain Sums Appropriated in Republic Act Numbered Twelve Hundred","orig":"An Act Reappropriating Certain Sums Appropriated in Republic Act Numbered Twelve Hundred"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2819","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2819_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2546-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sums appropriated in item (50), page 504, and items (59), (61) and (70), page 505, paragraph aa, for the Province of Leyte, Section two of Republic Act Numbered Twelve hundred, to wit:\n\"(50) Reconstruction of two-room building, Atabay Barrio School, Hilongos ₱1,000.00 \"(59) Reconstruction of Magnangoy Barrio School, Hilongos 1,000.00 \"(61) Reconstruction of San Juan Barrio School, Hilongos 1,000.00 \"(70) Reconstruction of San Roque Barrio School, Hilongos 1,000.00.\" are hereby reappropriated for the following purposes:\n(1) Completion of Sta. Margarita Barrio School building, Hilongos ₱2,000.00\n(2) Completion of Tuguipa Barrio School building, Hilongos 2,000.00"}},{"id":"PH-H2546-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2547"] = {"id":"PH-H2547","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2820_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Bato市","en":"An Act Creating Certain Barrios in the Municipality of Bato, Province of Catanduanes","orig":"An Act Creating Certain Barrios in the Municipality of Bato, Province of Catanduanes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2820","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2820_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2547-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Bato, Province of Catanduanes, are converted into barrios therein, to wit:\n1. Sitio Mintay to Barrio Mintay;\n2. Sitio Carorian to Barrio Carorian; and\n3. Sitio Buenavista to Barrio Buenavista."}},{"id":"PH-H2547-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2548"] = {"id":"PH-H2548","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2821_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Panabo市","en":"An Act Creating Certain Barrios in the Municipality of Panabo, Province of Davao","orig":"An Act Creating Certain Barrios in the Municipality of Panabo, Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2821","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2821_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2548-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Panabo, Province of Davao, are converted or constituted into barrios therein, to wit:\n1. Sitio Magopsing, to be known as the barrio of Magopsing; and\n2. Sitios of Carriedo and New Camiling, into a distinct and independent barrio, to be known as the barrio of Alejal."}},{"id":"PH-H2548-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2549"] = {"id":"PH-H2549","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2822_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Names of Certain Barrios in the Municipality of Panabo, Province of Davao","orig":"An Act Changing the Names of Certain Barrios in the Municipality of Panabo, Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2822","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2822_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2549-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The names of the following barrios in the Municipality of Panabo, Province of Davao, are changed as follows:\n1. Barrio Upper Catungan to Barrio Sta. Cruz; and\n2. Barrio Southern Manay to Barrio Casilac."}},{"id":"PH-H2549-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2550"] = {"id":"PH-H2550","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2823_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting Sitio Caligangan, Municipality of Liloan, Province of Leyte, into a Barrio","orig":"An Act Converting Sitio Caligangan, Municipality of Liloan, Province of Leyte, into a Barrio"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2823","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2823_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2550-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sitio Caligangan, Municipality of Liloan, Province of Leyte, is hereby converted into a barrio to be known as Barrio Caligangan."}},{"id":"PH-H2550-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2551"] = {"id":"PH-H2551","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2824_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Palompon市","en":"An Act Creating Certain Barrios in the Municipality of Palompon, Province of Leyte","orig":"An Act Creating Certain Barrios in the Municipality of Palompon, Province of Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2824","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2824_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2551-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Cantandoy, Tambis and Oguinsan in the Municipality of Palompon, Province of Leyte, are converted into barrios of said municipality to be known as the barrios of Cantandoy, Tambis and Oguinsan, respectively."}},{"id":"PH-H2551-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2552"] = {"id":"PH-H2552","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2825_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Second District of the Province of Batangas","orig":"An Act Creating Certain Barrios in the Second District of the Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2825","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2825_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2552-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Bauan, Province of Batangas, are constituted as barrios therein to wit:\n(a) The sitio of Look is separated from barrio Culbo and the sitio of Look is separated from barrio Magalangalang, and are constituted into a distinct and independent barrio, to be known as the barrio of Bagong Silang; and\n(b) The sitios of Tubuhan and San Gelacio are separated from the barrio of Malaking Pook, and constituted into a distinct and independent barrio, to be known as the barrio of Resplandor."}},{"id":"PH-H2552-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The following sitios in the Municipality of Batangas, same province, are constituted as barrios therein, to wit:\n(a) Sitio of Pook, barrio Mahabang-Parang, is converted into a barrio, to be known as the barrio of Sorosorong Ilaya, and sitio of Sorosorong Bundoc is converted into a barrio, to be known as the barrio of Sorosorong Ibaba; the boundary line between these barrios shall be a straight line running from East to West passing through the center of the barrio school building of Sorosoro;\n(b) Sitio of Sorosorong Carzada is converted into a barrio, to be known as the barrio of Sorosorong Carzada;\n(c) Sitio Pook ni Mestisa is converted into a barrio, to be known as the barrio of Banabang Silañgan;\n(d) Sitio Ilaya is converted into a barrio, to be known as the barrio of Banabang Ilaya;\n(e) Sitios Magbabanig, Apple and Ibaba are constituted into a distinct and independent barrio, to be known as the barrio of Banabang Ibaba;\n(f) Sitios of Kanluran, Silangang Carzada before Mangahan, Balimbing and Guitnang Pook are constituted into a distinct and independent barrio, to be known as the barrio Banabang Kanluran; and\n(g) The sitio of Saimsim is separated from barrio Haliguing Kanluran, the sitio of Igat is separated from barrio Simlong, and the sitio of Piit is separated from barrio Pinamucan, and are constituted into a distinct and independent barrio, to be known as the barrio of Pinamucan Silangan."}},{"id":"PH-H2552-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2553"] = {"id":"PH-H2553","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2826_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Municipal of Dumingag, Province of Zamboanga del Sur","orig":"An Act Creating Certain Barrios in the Municipal of Dumingag, Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2826","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2826_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2553-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Dumingag, Province of Zamboanga del Sur, are converted into barrios of said municipality, to wit:\nSitio Bag-ong Basak to Barrio Bag-ong Basak;\nSitio Bag-ong Princesa to Barrio Bag-ong Princesa;\nSitio Bag-ong Valencia to Barrio Bag-ong Valencia;\nSitio Bocayan to Barrio Bocayan;\nSitio Boniao to Barrio Boniao;\nSitio Calumangi to Barrio Calumangi;\nSitio Dapiwak to Barrio Dapiwak;\nSitio Dekayo to Barrio Dekayo;\nSitio Ditolan to Barrio Ditolan;\nSitio Gelicton to Barrio Gelicton;\nSitio Gonain to Barrio Gonain;\nSitio Guintananan to Barrio Guintananan;\nSitio Guitran to Barrio Guitran;\nSitio Landing to Barrio Landing;\nSitio Manguilos to Barrio Manguilos;\nSitio Macasing to Barrio Macasing;\nSitio Mahayahay to Barrio Mahayahay;\nSitio Maralag to Barrio Maralag;\nSitio Marañgan to Barrio Marañgan;\nSitio Palili to Barrio Palili;\nSitio Paraiso to Barrio Paraiso;\nSitio Poguan to Barrio Poguan;\nSitio Santa Cruz to Barrio Santa Cruz;\nSitio Senoto to Barrio Senoto;\nSitio Timonan (Lower) to Barrio Timonan (Lower);\nSitio Timonan (Upper) to Barrio Timonan (Upper);\nSitio Tuñgawan to Barrio Tuñgawan;\nSitio Tuboy to Barrio Tuboy; and\nSitio Yabu to Barrio Yabu."}},{"id":"PH-H2553-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2554"] = {"id":"PH-H2554","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2827_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Barrio Mongolbongol in the Municipality of Capul, Province of Samar, to San Vicente","orig":"An Act Changing the Name of Barrio Mongolbongol in the Municipality of Capul, Province of Samar, to San Vicente"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2827","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2827_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2554-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of barrio Mongolbongol in the Municipality of Capul, Province of Samar, is changed to San Vicente."}},{"id":"PH-H2554-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2555"] = {"id":"PH-H2555","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2828_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Naujan市","en":"An Act Creating Certain Barrios in the Municipality of Naujan, Province of Oriental Mindoro","orig":"An Act Creating Certain Barrios in the Municipality of Naujan, Province of Oriental Mindoro"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2828","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2828_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2555-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Naujan, Province of Oriental Mindoro, are separated from their respective barrios and constituted into distinct and independent barrios therein to wit:\n1. The sitios of San Agustin Ilaya, Kabilang Ilog, Mangaya and San Andres of the barrio of San Agustin No. 1, to be known as the barrio of San Agustin;\n2. The sitios of Butik Proper, Labak, Ibulo and Bukayao Grande of the barrio of Tagumpay, to be known as the barrio of San Andres;\n3. The sitios of Arangin Proper, Bagtu ng Arangin, Bansana, Barumbong and Kaowayan of the barrio of Malvar, to be known as the barrio of Arangin; and\n4. The sitios of Paitan, Bandol, Bugayan and Timbolaten of the barrio of Evangelista, to be known as the barrio of Metolza (Paitan)."}},{"id":"PH-H2555-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2556"] = {"id":"PH-H2556","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2829_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立DARaga市","en":"An Act Creating the Barrio of Madaat in the Municipality of DARaga, Province of Albay","orig":"An Act Creating the Barrio of Madaat in the Municipality of DARaga, Province of Albay"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2829","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2829_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2556-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Madaat in the barrio of San Vicente Grande, Municipality of Daraga, Province of Albay is converted into a barrio of said municipality to be known as the barrio of Madaat."}},{"id":"PH-H2556-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
