  FT["PH-H2558"] = {"id":"PH-H2558","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2831_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Baybay National Agricultural School in the Municipality of Baybay, Province of Leyte, to Visayas Agricultural College","orig":"An Act Changing the Name of the Baybay National Agricultural School in the Municipality of Baybay, Province of Leyte, to Visayas Agricultural College"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 2831","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2831_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2558-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Baybay National Agricultural School located in the Municipality of Baybay, Province of Leyte, is hereby changed to Visayas Agricultural College, to conform with the status and types of curricula which the school offers."}},{"id":"PH-H2558-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Visayas Agricultural College shall continue to be administered by the Bureau of Public Schools."}},{"id":"PH-H2558-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2559"] = {"id":"PH-H2559","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2832_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Certain Items in Republic Act Numbered Fourteen Hundred Eleven","orig":"An Act Amending Certain Items in Republic Act Numbered Fourteen Hundred Eleven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2832","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2832_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 3 条，缺 2）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2559-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (ad), page 76, group I, subparagraph (25), for the Province of Laguna, paragraph f, Section two of Republic Act Numbered Fourteen hundred eleven is amended to read as follows:\n\"(ad) Municipal Hall, Alaminos—Construction ₱1,000.00\"\nSection 2. Item 3, for the Province of Laguna, page 202, paragraph g, Section two of the same Act is amended to read as follows:\n\"3. Municipal Hall, Alaminos—Construction ₱2,000.00\""}},{"id":"PH-H2559-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2560"] = {"id":"PH-H2560","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2833_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Alegria Street in the Municipality of Bilar, Province of Bohol, to Juan Luna Street","orig":"An Act Changing the Name of Alegria Street in the Municipality of Bilar, Province of Bohol, to Juan Luna Street"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2833","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2833_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2560-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Alegria Street in the Municipality of Bilar, Province of Bohol, is hereby changed to Juan Luna Street."}},{"id":"PH-H2560-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2561"] = {"id":"PH-H2561","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2834_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Clarin市","en":"An Act Converting the Clarin High School in the Municipality of Clarin, Province of Bohol, into a National School of Fisheries to be Known as the Clarin School of Fisheries, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Clarin High School in the Municipality of Clarin, Province of Bohol, into a National School of Fisheries to be Known as the Clarin School of Fisheries, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 2834","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2834_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2561-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Clarin High School in the Municipality of Clarin, Province of Bohol, is hereby converted into a national school of fisheries to be known as the Clarin School of Fisheries. The Secretary of Education is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H2561-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the conversion, operation and maintenance of said school during the fiscal year nineteen hundred sixty-one. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H2561-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
  FT["PH-H2562"] = {"id":"PH-H2562","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2835_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Midsayap市","en":"An Act Creating Certain Barrios in the Municipality of Midsayap, Province of Cotabato","orig":"An Act Creating Certain Barrios in the Municipality of Midsayap, Province of Cotabato"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2835","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2835_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2562-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Midsayap, Province of Cotabato, are converted into barrios therein to wit:\n1. Sitio Dado to Barrio Dado;\n2. Sitio Central Bulanan (Km. 52) to Barrio Central Bulanan (Km. 52);\n3. Sitio Malamonte to Barrio Malamonte;\n4. Sitio Samlang to Barrio Samlang;\n5. Sitio Kiloyno to Barrio Kiloyno;\n6. Sitio Biacnabato to Barrio Biacnabato;\n7. Sitio Kamanal to Barrio Kamanal; and\n8. Sitio Pacao to Barrio Pacao."}},{"id":"PH-H2562-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
