  FT["PH-H2565"] = {"id":"PH-H2565","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2838_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Names of Maningaw and Washington Streets in the Municipality of Bilar, Province of Bohol, to Marcelo H. Del Pilar Street and Magsaysay Street, Respectively","orig":"An Act Changing the Names of Maningaw and Washington Streets in the Municipality of Bilar, Province of Bohol, to Marcelo H. Del Pilar Street and Magsaysay Street, Respectively"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2838","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2838_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2565-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The names of Maningaw Street and Washington Street in the Municipality of Bilar, Province of Bohol, are hereby changed to Marcelo H. del Pilar Street and Magsaysay Street, respectively."}},{"id":"PH-H2565-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
