  FT["PH-H2567"] = {"id":"PH-H2567","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2840_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Mauban市","en":"An Act Converting the Sitio of Bagong Bayan, Barrio of Lual, Municipality of Mauban, Province of Quezon, into a Distinct and Independent Barrio to be Known as the District of Bagong Bayan","orig":"An Act Converting the Sitio of Bagong Bayan, Barrio of Lual, Municipality of Mauban, Province of Quezon, into a Distinct and Independent Barrio to be Known as the District of Bagong Bayan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2840","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2840_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2567-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Bagong Bayan is hereby separated from the barrio of Lual in the Municipality of Mauban, Province of Quezon, and is converted into a distinct and independent barrio to be known as the District of Bagong Bayan."}},{"id":"PH-H2567-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
