  FT["PH-H2581"] = {"id":"PH-H2581","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2854_1960.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Reappropriating Certain Sums Appropriated Under Republic Acts Numbered Nineteen Hundred, Twenty Hundred Ninety-Three, and Twenty-Three Hundred and One for the Construction of Certain Roads in the Municipality of Barili, Province of Cebu","orig":"An Act Reappropriating Certain Sums Appropriated Under Republic Acts Numbered Nineteen Hundred, Twenty Hundred Ninety-Three, and Twenty-Three Hundred and One for the Construction of Certain Roads in the Municipality of Barili, Province of Cebu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2854","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2854_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2581-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sums appropriated under item (c), page 263, subparagraph 18, paragraph f, Section two of Republic Act Numbered Nineteen hundred, and item 26, page 448, Province of Cebu, paragraph g, Section two of Republic Act Numbered Nineteen hundred are hereby reappropriated for the construction of the Giloctogside-Aloguisan Road in the Municipality of Barili, Province of Cebu, as item VI (c), and as item 50a, subparagraph \"Cebu\" of paragraph g, respectively, both of Section two of the said Act."}},{"id":"PH-H2581-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sums appropriated under item (b), Group VI, page 207, subparagraph 18, paragraph f, Title M, Section one of Republic Act Numbered Twenty hundred ninety-three, and item 2, page 328, Province of Cebu, paragraph g, Title M, Section one of Republic Act Numbered Twenty hundred ninety-three are hereby reappropriated for the construction of the Dakit-Bolocboloc Road in the Municipality of Barili, Province of Cebu, as item VI (b), subparagraph 18 of paragraph f and as item 27 (a), subtitle \"Roads and Street,\" subparagraph \"Cebu\" of paragraph g, respectively, both of Title M, Section one of the said Act."}},{"id":"PH-H2581-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum appropriated under item 4, page 528, Province of Cebu, paragraph e, Section two of Republic Act Numbered Twenty-three hundred and one is hereby reappropriated for the construction of the Poblacion-Balao Road in the Municipality of Barili, Province of Cebu, as item 20(a), sub-title \"Roads,\" subparagraph \"Cebu\" of paragraph e, Section two of said Act."}},{"id":"PH-H2581-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The items whose appropriations are hereby reappropriated are repealed."}},{"id":"PH-H2581-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p36"};
